<?php
namespace App\Http\Controllers\Api\Admin; use App\Http\Controllers\Controller; use Illuminate\Http\JsonResponse; use Illuminate\Http\Request; use Illuminate\Support\Facades\DB; use Illuminate\Support\Str; use Illuminate\Validation\Rule;
class LogisticsExceptionController extends Controller { public function index(Request$r):JsonResponse{$this->permit($r,'logistics.view');$f=$r->validate(['search'=>['nullable','string','max:150'],'status'=>['nullable','string','max:30'],'severity'=>['nullable','string','max:20'],'type'=>['nullable','string','max:80'],'sort'=>['nullable',Rule::in(['created_at','updated_at','reference','severity','status'])],'direction'=>['nullable',Rule::in(['asc','desc'])],'per_page'=>['nullable','integer','between:1,100']]);$q=$this->query($f);$rows=(clone$q)->leftJoin('shipments as s','s.id','=','le.shipment_id')->leftJoin('return_cases as rc','rc.id','=','le.return_case_id')->leftJoin('logistics_partners as lp','lp.id','=','le.logistics_partner_id')->select('le.*','s.shipment_number','rc.return_number','lp.name as carrier_name')->orderBy('le.'.($f['sort']??'created_at'),$f['direction']??'desc')->paginate($f['per_page']??25);return response()->json(['data'=>['records'=>$rows,'intelligence'=>$this->intel($q)]]);} public function store(Request$r):JsonResponse{$this->permit($r,'logistics.create');$d=$r->validate(['exception_type'=>['required','string','max:80'],'severity'=>['required',Rule::in(['critical','high','medium','low'])],'shipment_id'=>['nullable','integer','exists:shipments,id'],'return_case_id'=>['nullable','integer','exists:return_cases,id'],'expected_amount'=>['nullable','numeric','min:0'],'actual_amount'=>['nullable','numeric','min:0'],'notes'=>['nullable','string','max:4000']]);$d['uuid']=(string)Str::uuid();$d['reference']='LEX-'.now()->format('Y').'-'.str_pad((string)((DB::table('logistics_exceptions')->max('id')??0)+1),6,'0',STR_PAD_LEFT);$d['created_at']=$d['updated_at']=now();$id=DB::table('logistics_exceptions')->insertGetId($d);activity('admin')->causedBy($r->user())->withProperties(['exception_id'=>$id])->log('logistics_exception.created');return response()->json(['data'=>['record'=>DB::table('logistics_exceptions')->find($id)]],201);} public function status(Request$r,string$id):JsonResponse{$this->permit($r,'logistics.update');$row=$this->find($id);abort_unless($row,404);$d=$r->validate(['status'=>['required',Rule::in(['open','assigned','under_review','escalated','resolved','closed'])]]);DB::table('logistics_exceptions')->where('id',$row->id)->update(['status'=>$d['status'],'updated_at'=>now()]);activity('admin')->causedBy($r->user())->withProperties(['exception_id'=>$row->id,'from'=>$row->status,'to'=>$d['status']])->log('logistics_exception.status_changed');return response()->json(['data'=>['record'=>$this->find((string)$row->id)]]);} public function reconcile(Request$r):JsonResponse{$this->permit($r,'logistics.update');$open=DB::table('logistics_exceptions')->whereNull('deleted_at')->where('reconciliation_status','unreconciled')->get();$matched=$open->filter(fn($x)=>(string)$x->expected_amount===(string)$x->actual_amount);DB::transaction(function()use($r,$open,$matched){DB::table('logistics_reconciliation_runs')->insert(['uuid'=>(string)Str::uuid(),'reference'=>'LREC-'.now()->format('YmdHis'),'scope'=>'all','status'=>'completed','processed_count'=>$open->count(),'matched_count'=>$matched->count(),'variance_count'=>$open->count()-$matched->count(),'run_by'=>$r->user()->id,'completed_at'=>now(),'created_at'=>now(),'updated_at'=>now()]);if($matched->isNotEmpty())DB::table('logistics_exceptions')->whereIn('id',$matched->pluck('id'))->update(['reconciliation_status'=>'reconciled','updated_at'=>now()]);activity('admin')->causedBy($r->user())->withProperties(['processed'=>$open->count(),'matched'=>$matched->count()])->log('logistics_reconciliation.completed');});return response()->json(['data'=>['reconciled_count'=>$matched->count()],'message'=>'Reconciliation completed.']);} private function query($f){$q=DB::table('logistics_exceptions as le')->whereNull('le.deleted_at');foreach(['status','severity']as$k)if(!empty($f[$k]))$q->where('le.'.$k,$f[$k]);if(!empty($f['type']))$q->where('le.exception_type',$f['type']);if(!empty($f['search'])){$s='%'.$f['search'].'%';$q->where(fn($x)=>$x->where('le.reference','like',$s)->orWhere('le.exception_type','like',$s));}return$q;} private function intel($q){$open=(clone$q)->whereNotIn('le.status',['resolved','closed'])->count();return['healthScore'=>0,'healthTrendText'=>'—','priorityAlerts'=>[],'exceptionsSummary'=>['totalOpen'=>$open,'critical'=>(clone$q)->where('le.severity','critical')->count(),'high'=>(clone$q)->where('le.severity','high')->count()],'claimsSummary'=>['open'=>(clone$q)->where('le.record_type','claim')->count(),'pendingCarrierResponse'=>0,'overdue'=>0],'costSummary'=>['variancesCount'=>(clone$q)->whereColumn('le.expected_amount','<>','le.actual_amount')->count(),'unreconciledCost'=>(float)(clone$q)->where('le.reconciliation_status','unreconciled')->sum(DB::raw('ABS(expected_amount-actual_amount)'))],'reconciliationSummary'=>['unmatchedRecords'=>(clone$q)->where('le.reconciliation_status','unreconciled')->count(),'exceptionsCount'=>$open],'recoverySummary'=>['pendingRecoveriesCount'=>0,'overdueCount'=>0,'recoveredAmount'=>0],'controlSummary'=>['breaches'=>0,'slaBreaches'=>0,'holdsActive'=>0],'quickQueues'=>['exceptionsQueue'=>$open,'claimsQueue'=>0,'reconciliationQueue'=>(clone$q)->where('le.reconciliation_status','unreconciled')->count(),'recoveriesQueue'=>0]];} private function find($id){return DB::table('logistics_exceptions')->whereNull('deleted_at')->where(fn($q)=>$q->where('reference',$id)->orWhere('uuid',$id)->when(ctype_digit($id),fn($x)=>$x->orWhere('id',(int)$id)))->first();}private function permit($r,$p){abort_unless($r->user()->hasPermission($p),403);}}
